from collections import Counter,deque

def components(g):
 bg=Counter(v for row in g for v in row).most_common(1)[0][0]; seen=set(); comps=[]
 for r in range(len(g)):
  for c in range(len(g[0])):
   if g[r][c]==bg or (r,c) in seen: continue
   q=deque([(r,c)]); seen.add((r,c)); co=[]
   while q:
    y,x=q.popleft();co.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     ny,nx=y+dy,x+dx
     if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]!=bg and (ny,nx) not in seen:seen.add((ny,nx));q.append((ny,nx))
   comps.append(co)
 return bg,sorted([(len(co),(min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co))) for co in comps], reverse=True)
